//! Independent actual World choice/batch scenarios, separate from resolver checks.
use gielinor_world::{grinding,tool_crafting::{Recipe,Request},held_use::{Handler,Scope,Type,Request as Held},inventory::Item,simulation::{World,PlayerData,ActorId,Action,WorldEvent},stats::Stats,npc::RandomSource,hits::{Hit,Target,Style},CoordGrid};
use std::sync::Arc;
const PROFILES:[(i32,u16,u8);4]=[(21338,15,83),(21350,15,85),(21352,5,87),(25853,8,89)];
struct NoDraw;impl RandomSource for NoDraw{fn below(&mut self,_:u32)->u32{panic!("deterministic amethyst drew RNG")}}
fn fixture(index:usize,reverse:bool,existing:Option<i32>,rate:i32)->(World,ActorId,Request){
 let mut w=World::default();w.collision.allocate(3200,3200,0);let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_base(12,99);stats.set_current(12,99);stats.set_fine_xp(12,130344311).unwrap();let mut data=PlayerData::new(1,"Independent counted amethyst World".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);data.xp_rate_hundreds=rate;
 for s in 0..28{data.inventory.restore_slot(s,Some(Item{id:1931,count:1,vars:0})).unwrap();}for s in[0,1]{data.inventory.restore_slot(s,Some(Item{id:1755,count:1,vars:0})).unwrap();}for s in[3,9,17,26]{data.inventory.restore_slot(s,Some(Item{id:21347,count:1,vars:0})).unwrap();}data.inventory.restore_slot(27,Some(Item{id:995,count:1000,vars:0})).unwrap();if let Some(n)=existing{data.inventory.restore_slot(2,Some(Item{id:PROFILES[index].0,count:n,vars:0})).unwrap();}
 w.queue_login(1,data).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,true).unwrap();for id in[1755,21347]{w.held_use_types.insert(id,Type{id,content:-1});}for (id,_,_)in PROFILES{w.object_types.stackable.insert(id);}
 let recipes=Arc::new(PROFILES.into_iter().map(|(output,output_count,level)|Recipe{exchange:grinding::Recipe{tool:1755,input:21347,output,members:true,animation:Some(6295)},level,xp_tenths:600,output_count,ticks:1,name:"independent amethyst tips",action:"cut",failure:None}).collect());w.held_use_handlers.register(Scope::Types,1755,21347,Handler::ToolCraftingChoices{recipes,cycle_ticks:2}).unwrap();let h=if reverse{Held{selected_slot:17,selected_id:21347,target_slot:0,target_id:1755}}else{Held{selected_slot:0,selected_id:1755,target_slot:17,target_id:21347}};w.prepare_held_use(a,h).unwrap();w.finish_held_use(a,h).unwrap();let req=w.take_tool_crafting_request(a).unwrap().unwrap();assert_eq!(req.available(&w.data(a).unwrap().inventory),4);(w,a,req)
}
fn expected(w:&World,a:ActorId,before:&PlayerData,index:usize,existing:Option<i32>,done:usize,rate:i32){let mut inv=before.inventory.clone();for slot in[17,3,9,26].into_iter().take(done){inv.restore_slot(slot,None).unwrap();}if done>0{inv.restore_slot(if existing.is_some(){2}else{17},Some(Item{id:PROFILES[index].0,count:existing.unwrap_or(0)+done as i32*i32::from(PROFILES[index].1),vars:0})).unwrap();}let mut stats=before.stats.clone();stats.set_fine_xp(12,130344311+done as i32*(600*rate/100)).unwrap();assert_eq!(w.data(a).unwrap().inventory,inv);assert_eq!(w.data(a).unwrap().stats,stats);}

#[test]fn one_hundred_twelve_initial_refusals(){let mut n=0;for index in 0..4{for reverse in[false,true]{for mode in 0..14{let(mut w,a,req)=fixture(index,reverse,None,125);match mode{3=>w.set_membership(a,false).unwrap(),4=>w.data_mut(a).unwrap().stats.set_current(12,PROFILES[index].2 as i8-1),5=>w.data_mut(a).unwrap().xp_rate_hundreds=0,6=>{w.data_mut(a).unwrap().inventory.restore_slot(17,None).unwrap();},7=>{w.data_mut(a).unwrap().inventory.restore_slot(17,Some(Item{id:21347,count:1,vars:1})).unwrap();},8=>{w.data_mut(a).unwrap().inventory.restore_slot(0,None).unwrap();},9=>{w.data_mut(a).unwrap().inventory.restore_slot(0,Some(Item{id:1755,count:1,vars:1})).unwrap();},10=>{w.object_types.dummy.insert(PROFILES[index].0);},11=>w.set_modal_open(a,true).unwrap(),12=>w.request_logout(a).unwrap(),13=>w.data_mut(a).unwrap().xp_rate_hundreds=-1,_=>{}}let before=w.data(a).unwrap().clone();let result=w.start_tool_crafting_choice(a,req,if mode==0{4}else{index},if mode==1{0}else if mode==2{29}else{28});if mode<3{assert!(result.is_err());}for _ in 0..12{w.tick_with_random(&mut NoDraw).unwrap();}assert_eq!(w.data(a).unwrap().inventory,before.inventory,"index{index} reverse{reverse} initial{mode}");assert_eq!(w.data(a).unwrap().stats,before.stats);n+=1;}}}assert_eq!(n,112);}
#[test]fn one_hundred_twelve_late_changes_stop_after_one_whole_tip_credit(){let mut n=0;for index in 0..4{for reverse in[false,true]{for mode in 0..14{let(mut w,a,req)=fixture(index,reverse,None,125);let original=w.data(a).unwrap().clone();w.start_tool_crafting_choice(a,req,index,28).unwrap();for _ in 0..2{w.tick_with_random(&mut NoDraw).unwrap();}expected(&w,a,&original,index,None,1,125);match mode{0=>{w.data_mut(a).unwrap().inventory.restore_slot(3,Some(Item{id:1931,count:1,vars:0})).unwrap();w.data_mut(a).unwrap().inventory.restore_slot(25,Some(Item{id:21347,count:1,vars:0})).unwrap();},1=>{w.data_mut(a).unwrap().inventory.restore_slot(3,Some(Item{id:21347,count:1,vars:1})).unwrap();},2=>{w.data_mut(a).unwrap().inventory.restore_slot(0,None).unwrap();},3=>{w.data_mut(a).unwrap().inventory.restore_slot(0,Some(Item{id:1755,count:1,vars:1})).unwrap();},4=>w.set_membership(a,false).unwrap(),5=>w.data_mut(a).unwrap().stats.set_current(12,PROFILES[index].2 as i8-1),6=>w.data_mut(a).unwrap().xp_rate_hundreds=0,7=>{w.object_types.dummy.insert(PROFILES[index].0);},8=>{w.set_modal_open(a,true).unwrap();w.set_modal_open(a,false).unwrap();},9=>w.submit(a,Action::Walk{destination:CoordGrid::new(3201,3200,0).unwrap(),run:false}).unwrap(),10=>{w.close_dialogs(a).unwrap();},11=>w.request_logout(a).unwrap(),12=>w.data_mut(a).unwrap().stats.set_current(3,0),_=>{w.queue_hit(Target::Player(a),Hit{display:None,source:None,style:Style::Typeless,damage:20},1).unwrap();w.tick_with_random(&mut NoDraw).unwrap();assert_eq!(w.data(a).unwrap().stats.current(3),0);assert!(w.drain_events().iter().any(|e|matches!(e,WorldEvent::DeathRequested(_))));w.data_mut(a).unwrap().stats.set_current(3,10);}}let before=w.data(a).unwrap().clone();for _ in 0..12{w.tick_with_random(&mut NoDraw).unwrap();}assert_eq!(w.data(a).unwrap().inventory,before.inventory,"index{index} reverse{reverse} late{mode}");assert_eq!(w.data(a).unwrap().stats,before.stats);n+=1;}}}assert_eq!(n,112);}
